{
  "contract": "TraderSpirits",
  "closure": {
    "site_function": "mintByUser",
    "site_call": ".call",
    "functions": [
      "mintByUser"
    ],
    "justification": "mintByUser is the only function that modifies the exposed storage variables and can be re-entered."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "mintByUser"
    ],
    "nesting_bound": {
      "mintByUser": 1
    }
  },
  "phases": {
    "function": "mintByUser",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [],
  "exposure_invariant": {
    "formula": "publicMinted <= publicMintLimit",
    "stable_formula": "publicMinted <= publicMintLimit",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "publicMinted <= publicMintLimit",
    "rule": "The exposure invariant is the same as the stable invariant because the target property reads variables that are not modified before the call."
  }
}
